xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;500;700;900&display=swap');

/* ═══════════════════════════════════════════
   ※ .xt-text 通用兜底 ※ 必须最前 ※
   ═══════════════════════════════════════════ */
.xt-text{
  background:#fff!important;color:#18191C!important;
  font-size:14px!important;line-height:1.7!important;
  padding:10px 14px!important;margin:0!important;
  border:none!important;border-radius:0!important;
}

/* ═══════════════════════════════════════════
   全局
   ═══════════════════════════════════════════ */
.xt-root{
  --bp:#FB7299;--bpd:#D45980;--bb:#00AEEC;--bbd:#0092C8;
  --pg:#F4F5F7;--wt:#FFF;--tx:#18191C;--tx2:#61666D;--tx3:#9499A0;--ln:#E3E5E7;
  --wg:#EDEDED;--wgw:#FFF;--wgt:#07C160;
  --xt-bg:var(--pg);--xt-text:var(--tx);--xt-text-sub:var(--tx2);--xt-text-muted:var(--tx3);
  --xt-accent:var(--bp);--xt-accent-bg:rgba(251,114,153,.08);
  --xt-border:var(--ln);--xt-radius:10px;--xt-radius-sm:6px;
  --xt-font:'Noto Sans SC',system-ui,sans-serif;
  background:var(--pg)!important;padding:0!important;
  border-radius:12px!important;border:1px solid var(--ln)!important;
  box-shadow:0 4px 20px rgba(0,0,0,.08)!important;position:relative!important;
}
.xt-root::before,.xt-root::after{content:none!important;display:none!important;}
.xt-content{padding:0 0 14px!important;margin-top:0!important;}

/* ═══════════════════════════════════════════
   弹幕
   ═══════════════════════════════════════════ */
.xt-marquee{
  position:absolute!important;left:0!important;right:0!important;
  background:transparent!important;border:none!important;
  height:24px!important;padding:0!important;margin:0!important;
  pointer-events:none!important;overflow:hidden!important;
  display:none!important;z-index:20!important;
}
.xt-marquee:nth-of-type(3n+1){top:12px!important;}
.xt-marquee:nth-of-type(3n+2){top:40px!important;}
.xt-marquee:nth-of-type(3n+3){top:68px!important;}
.xt-marquee .xt-marquee-inner,.xt-marquee .xt-marquee-inner *,.xt-marquee .xt-marquee-inner span{
  font-size:14px!important;font-weight:700!important;line-height:24px!important;
  text-shadow:-1px 0 1px #000,1px 0 1px #000,0 -1px 1px #000,0 1px 1px #000,0 0 6px rgba(0,0,0,.8)!important;
}
.xt-marquee:nth-of-type(1) .xt-marquee-inner,.xt-marquee:nth-of-type(1) .xt-marquee-inner *{color:#FFF!important;animation-duration:10s!important;}
.xt-marquee:nth-of-type(2) .xt-marquee-inner,.xt-marquee:nth-of-type(2) .xt-marquee-inner *{color:#FFE438!important;animation-duration:14s!important;}
.xt-marquee:nth-of-type(3) .xt-marquee-inner,.xt-marquee:nth-of-type(3) .xt-marquee-inner *{color:#FF9BB3!important;animation-duration:7.5s!important;}
.xt-marquee:nth-of-type(4) .xt-marquee-inner,.xt-marquee:nth-of-type(4) .xt-marquee-inner *{color:#7EFF9B!important;animation-duration:9s!important;}
.xt-marquee:nth-of-type(5) .xt-marquee-inner,.xt-marquee:nth-of-type(5) .xt-marquee-inner *{color:#FFF!important;animation-duration:11.5s!important;}
.xt-marquee:nth-of-type(6) .xt-marquee-inner,.xt-marquee:nth-of-type(6) .xt-marquee-inner *{color:#63D0FF!important;animation-duration:6.5s!important;}
.xt-marquee:nth-of-type(7) .xt-marquee-inner,.xt-marquee:nth-of-type(7) .xt-marquee-inner *{color:#FFE438!important;animation-duration:8.5s!important;}
.xt-marquee:nth-of-type(8) .xt-marquee-inner,.xt-marquee:nth-of-type(8) .xt-marquee-inner *{color:#FF9BB3!important;animation-duration:12s!important;}
.xt-marquee:nth-of-type(9) .xt-marquee-inner,.xt-marquee:nth-of-type(9) .xt-marquee-inner *{color:#FFF!important;animation-duration:7s!important;}
.xt-marquee:nth-of-type(10) .xt-marquee-inner,.xt-marquee:nth-of-type(10) .xt-marquee-inner *{color:#7EFF9B!important;animation-duration:10s!important;}
.xt-marquee:nth-of-type(11) .xt-marquee-inner,.xt-marquee:nth-of-type(11) .xt-marquee-inner *{color:#63D0FF!important;animation-duration:11s!important;}
.xt-marquee:nth-of-type(12) .xt-marquee-inner,.xt-marquee:nth-of-type(12) .xt-marquee-inner *{color:#FFF!important;animation-duration:8s!important;}
.xt-marquee:nth-of-type(13) .xt-marquee-inner,.xt-marquee:nth-of-type(13) .xt-marquee-inner *{color:#FFE438!important;animation-duration:6.5s!important;}
.xt-marquee:nth-of-type(14) .xt-marquee-inner,.xt-marquee:nth-of-type(14) .xt-marquee-inner *{color:#FF9BB3!important;animation-duration:12s!important;}
.xt-marquee:nth-of-type(15) .xt-marquee-inner,.xt-marquee:nth-of-type(15) .xt-marquee-inner *{color:#FFF!important;animation-duration:7.5s!important;}
.xt-marquee:nth-of-type(1),.xt-marquee:nth-of-type(2),.xt-marquee:nth-of-type(3){display:block!important;}
#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(1),#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(2),#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(3){display:none!important;}
#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(4),#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(5),#xt-t1:checked~.xt-content .xt-marquee:nth-of-type(6){display:block!important;}
#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(4),#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(5),#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(6){display:none!important;}
#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(7),#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(8),#xt-t2:checked~.xt-content .xt-marquee:nth-of-type(9){display:block!important;}
#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(7),#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(8),#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(9){display:none!important;}
#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(10),#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(11),#xt-t3:checked~.xt-content .xt-marquee:nth-of-type(12){display:block!important;}
#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(10),#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(11),#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(12){display:none!important;}
#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(13),#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(14),#xt-t4:checked~.xt-content .xt-marquee:nth-of-type(15){display:block!important;}

/* ═══════════════════════════════════════════
   视频正片
   ═══════════════════════════════════════════ */
.xt-text-vid1,.xt-text-vid2,.xt-text-vid3,.xt-text-vid4,.xt-text-vid5{
  position:relative!important;
  padding:90px 24px 20px!important;min-height:240px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  text-align:center!important;color:rgba(255,255,255,.92)!important;
  font-size:15px!important;line-height:2.05!important;letter-spacing:.4px!important;
  text-shadow:0 1px 8px rgba(0,0,0,.65)!important;
  border:none!important;border-radius:0!important;margin:0!important;
  background:radial-gradient(ellipse 140% 120% at 50% 42%,#1a1520,#080608 78%)!important;
}
.xt-text-vid1::before,.xt-text-vid2::before,.xt-text-vid3::before,.xt-text-vid4::before,.xt-text-vid5::before{
  content:""!important;position:absolute!important;top:0!important;left:0!important;right:0!important;
  height:80px!important;background:linear-gradient(180deg,rgba(0,0,0,.7),transparent)!important;pointer-events:none!important;
}
.xt-text-vid1::after,.xt-text-vid2::after,.xt-text-vid3::after,.xt-text-vid4::after,.xt-text-vid5::after{
  content:"◉ REC  1080P60"!important;
  position:absolute!important;top:10px!important;left:14px!important;
  font-size:10px!important;font-weight:700!important;letter-spacing:1.2px!important;
  color:rgba(255,255,255,.4)!important;text-shadow:none!important;
}
.xt-text-vid2,.xt-text-vid3,.xt-text-vid4,.xt-text-vid5{display:none!important;}
#xt-t1:checked~.xt-content .xt-text-vid1{display:none!important;}
#xt-t1:checked~.xt-content .xt-text-vid2{display:flex!important;}
#xt-t2:checked~.xt-content .xt-text-vid2{display:none!important;}
#xt-t2:checked~.xt-content .xt-text-vid3{display:flex!important;}
#xt-t3:checked~.xt-content .xt-text-vid3{display:none!important;}
#xt-t3:checked~.xt-content .xt-text-vid4{display:flex!important;}
#xt-t4:checked~.xt-content .xt-text-vid4{display:none!important;}
#xt-t4:checked~.xt-content .xt-text-vid5{display:flex!important;}

/* ═══════════════════════════════════════════
   进度条 + 控制栏
   背景=进度条  ::before=左侧时间  ::after=右侧控制
   ═══════════════════════════════════════════ */
.xt-text.xt-text-playBar{
  position:relative!important;height:52px!important;
  margin:0!important;padding:0!important;
  font-size:0!important;color:transparent!important;
  border:none!important;border-radius:0!important;overflow:visible!important;
  background:#0a0a0a!important;
  background-image:linear-gradient(90deg,var(--bp) 12%,rgba(255,255,255,.18) 12%)!important;
  background-size:calc(100% - 28px) 3px!important;
  background-position:14px 8px!important;
  background-repeat:no-repeat!important;
}
.xt-text-playBar::before{
  content:"▶  00:18 / 04:25"!important;
  position:absolute!important;left:14px!important;bottom:10px!important;
  font-size:11px!important;color:rgba(255,255,255,.7)!important;
  letter-spacing:.2px!important;display:block!important;
}
.xt-text-playBar::after{
  content:"🔊  弹幕  ⚙  ⛶"!important;
  position:absolute!important;right:14px!important;bottom:10px!important;
  font-size:11px!important;color:rgba(255,255,255,.55)!important;
  letter-spacing:.5px!important;display:block!important;
}
#xt-t1:checked~.xt-content .xt-text.xt-text-playBar{background-image:linear-gradient(90deg,var(--bp) 30%,rgba(255,255,255,.18) 30%)!important;}
#xt-t1:checked~.xt-content .xt-text-playBar::before{content:"▶  01:06 / 04:25"!important;}
#xt-t2:checked~.xt-content .xt-text.xt-text-playBar{background-image:linear-gradient(90deg,var(--bp) 52%,rgba(255,255,255,.18) 52%)!important;}
#xt-t2:checked~.xt-content .xt-text-playBar::before{content:"▶  02:12 / 04:25"!important;}
#xt-t3:checked~.xt-content .xt-text.xt-text-playBar{background-image:linear-gradient(90deg,var(--bp) 75%,rgba(255,255,255,.18) 75%)!important;}
#xt-t3:checked~.xt-content .xt-text-playBar::before{content:"▶  03:20 / 04:25"!important;}
#xt-t4:checked~.xt-content .xt-text.xt-text-playBar{background-image:linear-gradient(90deg,var(--bp) 100%)!important;}
#xt-t4:checked~.xt-content .xt-text-playBar::before{content:"⏸  04:25 / 04:25"!important;}

/* ═══════════════════════════════════════════
   段切换按钮
   ═══════════════════════════════════════════ */
.xt-action-1,.xt-action-2,.xt-action-3,.xt-action-4{
  display:block!important;text-align:center!important;padding:12px!important;
  margin:0!important;border-radius:0!important;
  background:#111!important;color:rgba(255,255,255,.65)!important;
  font-size:12.5px!important;font-weight:500!important;letter-spacing:.5px!important;
  cursor:pointer!important;border-top:1px solid rgba(255,255,255,.05)!important;
}
.xt-action-2,.xt-action-3,.xt-action-4{display:none!important;}
.xt-action-1::after{content:"▷  下一段  01/05"!important;}
.xt-action-2::after{content:"▷  下一段  02/05"!important;}
.xt-action-3::after{content:"▷  下一段  03/05"!important;}
.xt-action-4::after{content:"▷  下一段  04/05"!important;}
#xt-t1:checked~.xt-content .xt-action-1{display:none!important;}
#xt-t1:checked~.xt-content .xt-action-2{display:block!important;}
#xt-t2:checked~.xt-content .xt-action-2{display:none!important;}
#xt-t2:checked~.xt-content .xt-action-3{display:block!important;}
#xt-t3:checked~.xt-content .xt-action-3{display:none!important;}
#xt-t3:checked~.xt-content .xt-action-4{display:block!important;}
#xt-t4:checked~.xt-content .xt-action-4{display:block!important;background:var(--bp)!important;color:#fff!important;pointer-events:none!important;}
#xt-t4:checked~.xt-content .xt-action-4::after{content:"✓  播放完毕  05/05"!important;}

/* ═══════════════════════════════════════════
   标题 + 播放量
   ═══════════════════════════════════════════ */
.xt-text-videoTitle{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:17px!important;font-weight:700!important;line-height:1.55!important;
  padding:14px 14px 5px!important;
}
.xt-text-playCount{
  background:var(--wt)!important;color:var(--tx3)!important;
  font-size:12.5px!important;padding:0 14px 12px!important;
}
.xt-text-playCount::before{content:"▶ "!important;}
.xt-text-playCount::after{content:"  ·  刚刚"!important;}

/* ═══════════════════════════════════════════
   标签
   ═══════════════════════════════════════════ */
.xt-tags{
  justify-content:flex-start!important;gap:6px!important;flex-wrap:wrap!important;
  background:var(--wt)!important;padding:0 14px 14px!important;margin:0!important;
  border-bottom:1px solid var(--ln)!important;
}
.xt-tag{
  background:rgba(0,174,236,.06)!important;color:var(--bbd)!important;
  border:1px solid rgba(0,174,236,.18)!important;border-radius:4px!important;
  padding:3px 10px!important;font-size:12px!important;font-weight:500!important;
}
.xt-tag::before{content:"# "!important;}
.xt-tag-cpName{background:rgba(251,114,153,.08)!important;color:var(--bpd)!important;border-color:rgba(251,114,153,.22)!important;font-weight:700!important;}
.xt-tag-cpName::before{content:"♥ "!important;}

/* ═══════════════════════════════════════════
   简介 collapse-5
   ═══════════════════════════════════════════ */
.xt-collapse-5{background:var(--wt)!important;border:none!important;border-bottom:1px solid var(--ln)!important;border-radius:0!important;margin:0!important;}
.xt-collapse-5 .xt-collapse-header{background:var(--wt)!important;color:var(--tx2)!important;font-size:13px!important;font-weight:500!important;padding:10px 14px!important;}
.xt-collapse-5 .xt-collapse-arrow{color:var(--tx3)!important;}
.xt-collapse-5 .xt-collapse-body{background:var(--wt)!important;padding:0 14px 12px!important;}
.xt-text-videoDesc{background:none!important;color:var(--tx2)!important;font-size:13px!important;line-height:1.75!important;padding:0!important;}

/* ═══════════════════════════════════════════
   UP主
   ═══════════════════════════════════════════ */
.xt-header{
  background:var(--wt)!important;
  border-top:1px solid var(--ln)!important;border-bottom:8px solid var(--pg)!important;
  margin:0!important;padding:14px!important;gap:12px!important;
  align-items:center!important;position:relative!important;border-radius:0!important;
}
.xt-avatar{width:48px!important;height:48px!important;border-radius:50%!important;border:2px solid var(--bp)!important;flex-shrink:0!important;}
.xt-name{color:var(--tx)!important;font-weight:700!important;font-size:15px!important;}
.xt-name::after{content:" · 632.8万粉丝"!important;font-size:12px!important;font-weight:400!important;color:var(--tx3)!important;}
.xt-header::after{content:"+ 关注"!important;position:absolute!important;right:14px!important;top:50%!important;transform:translateY(-50%)!important;font-size:14px!important;font-weight:700!important;color:#fff!important;background:var(--bp)!important;padding:8px 22px!important;border-radius:999px!important;box-shadow:0 4px 12px rgba(251,114,153,.25)!important;}

/* ═══════════════════════════════════════════
   评论区 collapse-6
   ═══════════════════════════════════════════ */
.xt-collapse-6{background:var(--wt)!important;border:none!important;border-top:8px solid var(--pg)!important;border-radius:0!important;margin:0!important;}
.xt-collapse-6 .xt-collapse-header{
  background:var(--wt)!important;color:var(--tx)!important;
  font-size:16px!important;font-weight:700!important;padding:14px!important;
  border-bottom:1px solid var(--ln)!important;pointer-events:none!important;
}
.xt-collapse-6 .xt-collapse-header::after{content:"  按热度"!important;font-size:12px!important;font-weight:400!important;color:var(--tx3)!important;}
.xt-collapse-6 .xt-collapse-arrow{display:none!important;}
.xt-collapse-6 .xt-collapse-body{max-height:9999px!important;overflow:visible!important;background:var(--wt)!important;padding:0 14px!important;}
.xt-collapse-6 .xt-list{padding:0!important;margin:0!important;}
.xt-collapse-6 .xt-list-item{
  display:block!important;position:relative!important;
  padding:14px 0 14px 50px!important;
  border-bottom:1px solid var(--ln)!important;
  color:var(--tx)!important;font-size:14px!important;line-height:1.7!important;
}
.xt-collapse-6 .xt-list-item:last-child{border-bottom:none!important;}
.xt-collapse-6 .xt-list-check{display:none!important;}
.xt-collapse-6 .xt-list-item::before{
  position:absolute!important;left:0!important;top:14px!important;
  width:38px!important;height:38px!important;border-radius:50%!important;
  font-size:18px!important;line-height:38px!important;text-align:center!important;display:block!important;
}
.xt-collapse-6 .xt-list-item:nth-child(1)::before{content:"🌟"!important;background:#FFFBE6!important;}
.xt-collapse-6 .xt-list-item:nth-child(2)::before{content:"🌸"!important;background:#FFF0F5!important;}
.xt-collapse-6 .xt-list-item:nth-child(3)::before{content:"🎵"!important;background:#EFF8FF!important;}
.xt-collapse-6 .xt-list-item:nth-child(4)::before{content:"🔥"!important;background:#FFF4EE!important;}
.xt-collapse-6 .xt-list-item:nth-child(5)::before{content:"💫"!important;background:#F6F0FF!important;}
.xt-collapse-6 .xt-list-item:nth-child(6)::before{content:"🍬"!important;background:#F0FFF5!important;}
.xt-collapse-6 .xt-list-text{display:block!important;color:var(--tx)!important;font-size:14px!important;line-height:1.7!important;word-break:break-word!important;white-space:normal!important;}
.xt-collapse-6 .xt-list-item:nth-child(-n+3) .xt-list-text::before{
  content:"热评"!important;font-size:10px!important;font-weight:700!important;color:var(--bp)!important;
  background:rgba(251,114,153,.1)!important;padding:1px 5px!important;border-radius:3px!important;margin-right:6px!important;
}
.xt-collapse-6 .xt-list-item::after{display:block!important;font-size:12px!important;color:var(--tx3)!important;margin-top:8px!important;}
.xt-collapse-6 .xt-list-item:nth-child(1)::after{content:"1天前   👍 2.1万   💬 148"!important;}
.xt-collapse-6 .xt-list-item:nth-child(2)::after{content:"8小时前   👍 8964   💬 76"!important;}
.xt-collapse-6 .xt-list-item:nth-child(3)::after{content:"3小时前   👍 3.2万   💬 214"!important;}
.xt-collapse-6 .xt-list-item:nth-child(4)::after{content:"2小时前   👍 1.5万   💬 92"!important;}
.xt-collapse-6 .xt-list-item:nth-child(5)::after{content:"1小时前   👍 762   💬 31"!important;}
.xt-collapse-6 .xt-list-item:nth-child(6)::after{content:"45分钟前   👍 443   💬 17"!important;}

/* ═══════════════════════════════════════════
   微信群聊 collapse-7 · 无头像 · 气泡上方显名字
   ═══════════════════════════════════════════ */
.xt-collapse-7{
  background:var(--wg)!important;
  border:none!important;border-top:8px solid var(--pg)!important;
  border-radius:0!important;margin:0!important;overflow:hidden!important;
}
/* 微信顶栏：隐藏固定文字"微信"，用 wcName 字段显示群名 */
.xt-collapse-7 .xt-collapse-header{
  background:#EDEDED!important;color:transparent!important;
  font-size:0!important;
  padding:0!important;height:0!important;overflow:hidden!important;
  border:none!important;pointer-events:none!important;
}
.xt-collapse-7 .xt-collapse-arrow{display:none!important;}
.xt-collapse-7 .xt-collapse-body{
  max-height:9999px!important;overflow:visible!important;
  background:var(--wg)!important;padding:0!important;
}
/* wcName → 微信顶栏标题 */
.xt-text-wcName{
  background:#EDEDED!important;color:var(--tx)!important;
  font-size:16px!important;font-weight:500!important;
  text-align:center!important;padding:10px 44px!important;margin:0!important;
  border-bottom:.5px solid #D0D0D0!important;
  position:relative!important;
}
.xt-text-wcName::before{
  content:"❮"!important;position:absolute!important;left:14px!important;top:50%!important;
  transform:translateY(-50%)!important;font-size:16px!important;font-weight:400!important;color:var(--tx)!important;
}
.xt-text-wcName::after{
  content:"⋯"!important;position:absolute!important;right:14px!important;top:50%!important;
  transform:translateY(-50%)!important;font-size:18px!important;font-weight:700!important;color:var(--tx)!important;
}
/* 群聊消息 */
.xt-collapse-7 .xt-list{padding:8px 12px 12px!important;margin:0!important;}
